export interface LCSResult {
  substring: string;
  length: number;
}

/**
 * Longest common substring (case-insensitive), O(n*m) DP.
 * Returns null if no substring of at least minLen exists.
 */
export function longestCommonSubstring(a: string, b: string, minLen: number = 1): LCSResult | null {
  const s1 = (a || '').toLowerCase();
  const s2 = (b || '').toLowerCase();
  const n = s1.length;
  const m = s2.length;
  if (n === 0 || m === 0) return null;

  const dp: number[] = new Array(m + 1).fill(0);
  let maxLen = 0;
  let endIndexS1 = 0;

  for (let i = 1; i <= n; i++) {
    let prev = 0;
    for (let j = 1; j <= m; j++) {
      const temp = dp[j];
      if (s1[i - 1] === s2[j - 1]) {
        dp[j] = prev + 1;
        if (dp[j] > maxLen) {
          maxLen = dp[j];
          endIndexS1 = i; // s1 index is 1-based in this loop
        }
      } else {
        dp[j] = 0;
      }
      prev = temp;
    }
  }

  if (maxLen < minLen) return null;
  const start = endIndexS1 - maxLen;
  let substr = (a || '').substring(start, endIndexS1); // original casing
  // Trim spaces on both ends; keep internal spaces
  const trimmed = substr.replace(/^\s+|\s+$/g, '');
  if (trimmed.length < minLen) return null;
  return { substring: trimmed, length: trimmed.length };
}


