import { Motif } from '../types/motif';
import motifsData from '../data/motifs.json';
import { MotifBead } from './MotifBead';
import { MotifBeadManager } from './MotifBeadManager';
import { GameSettingsStorage, FusionAreas } from './gameSettingsStorage';
import { EmbeddingIndex } from './embeddingIndex';
import type { Language } from './languageContext';

type Rect = { x: number; y: number; w: number; h: number };

export class FusionManager {
  private beadManager: MotifBeadManager;
  private storage: GameSettingsStorage;
  private index: EmbeddingIndex;

  constructor() {
    this.beadManager = MotifBeadManager.getInstance();
    this.storage = new GameSettingsStorage();
    this.index = new EmbeddingIndex();
  }

  async getAreas(): Promise<{
    fusionAreas: FusionAreas;
    inputShape: any | null;
    outputShape: any | null;
  }> {
    const fusionAreas = await this.storage.loadFusionAreas();
    const inputShape = fusionAreas.inputShapeId
      ? await this.safeGetById(fusionAreas.inputShapeId)
      : null;
    const outputShape = fusionAreas.outputShapeId
      ? await this.safeGetById(fusionAreas.outputShapeId)
      : null;
    return { fusionAreas, inputShape, outputShape };
  }

  private async safeGetById(id: string): Promise<any | null> {
    try {
      const item = await window.miro.board.get({ id });
      if (!item) return null;
      if (Array.isArray(item)) return item[0] || null;
      return item;
    } catch {
      return null;
    }
  }

  async setInputAreaFromSelection(): Promise<FusionAreas> {
    const selection = await window.miro.board.getSelection();
    if (!selection || selection.length === 0) throw new Error('Select a shape.');
    const shape = selection.find((s: any) => s.type === 'shape') || selection[0];
    const current = await this.storage.loadFusionAreas();
    const updated: FusionAreas = { ...current, inputShapeId: shape.id };
    await this.storage.saveFusionAreas(updated);
    return updated;
  }

  async setOutputAreaFromSelection(): Promise<FusionAreas> {
    const selection = await window.miro.board.getSelection();
    if (!selection || selection.length === 0) throw new Error('Select a shape.');
    const shape = selection.find((s: any) => s.type === 'shape') || selection[0];
    const current = await this.storage.loadFusionAreas();
    const updated: FusionAreas = { ...current, outputShapeId: shape.id };
    await this.storage.saveFusionAreas(updated);
    return updated;
  }

  private toRect(item: any): Rect {
    // Some shapes may not have width/height populated until synced; ensure numbers
    const w = typeof item.width === 'number' ? item.width : (item.bounds?.width ?? 0);
    const h = typeof item.height === 'number' ? item.height : (item.bounds?.height ?? 0);
    return { x: item.x, y: item.y, w, h };
  }

  private insideRect(p: { x: number; y: number }, r: Rect): boolean {
    return (
      p.x >= r.x - r.w / 2 &&
      p.x <= r.x + r.w / 2 &&
      p.y >= r.y - r.h / 2 &&
      p.y <= r.y + r.h / 2
    );
  }

  async collectInputBeads(): Promise<MotifBead[]> {
    const { inputShape } = await this.getAreas();
    if (!inputShape) return [];
    const rect = this.toRect(inputShape);
    const beads = this.beadManager.getAllBeads();
    if (beads.length === 0) return [];

    // Prefer image centers for inclusion test (more reliable)
    const imageIds: string[] = beads.map(b => b.getImageId());
    let images: any[] = [];
    try {
      images = await window.miro.board.get({ id: imageIds, type: 'image' });
    } catch {
      images = [];
    }
    const imagesById = new Map<string, any>();
    for (const img of images) imagesById.set(img.id, img);

    const result: MotifBead[] = [];
    for (const bead of beads) {
      try {
        const img = imagesById.get(bead.getImageId());
        const cx = img?.x;
        const cy = img?.y;
        if (typeof cx === 'number' && typeof cy === 'number') {
          if (this.insideRect({ x: cx, y: cy }, rect)) {
            result.push(bead);
          }
        } else {
          // Fallback to per-bead position if image not found
          try {
            const pos = await bead.getPosition();
            if (this.insideRect(pos, rect)) result.push(bead);
          } catch {
            // Do not remove the bead; just skip if position cannot be determined
          }
        }
      } catch {
        // ignore beads we cannot position
      }
    }
    return result;
  }

  computeFusionEmbedding(beads: MotifBead[]): number[] | null {
    const vectors: number[][] = [];
    for (const bead of beads) {
      const emb = bead.getEmbedding();
      if (emb && emb.length > 0) vectors.push(emb);
    }
    if (vectors.length === 0) return null;
    const dim = vectors[0].length;
    const avg = new Array(dim).fill(0);
    for (const v of vectors) {
      for (let i = 0; i < dim; i++) avg[i] += v[i];
    }
    for (let i = 0; i < dim; i++) avg[i] /= vectors.length;
    return avg;
  }

  findResultMotif(avg: number[], excludeIds: Set<string>): Motif | null {
    return this.index.nearest(avg, excludeIds);
  }

  async spawnResult(motif: Motif, centerOverride?: { x: number; y: number }): Promise<MotifBead> {
    let center = centerOverride;
    if (!center) {
      const { outputShape } = await this.getAreas();
      if (!outputShape) throw new Error('Output area not set.');
      center = { x: outputShape.x, y: outputShape.y };
    }
    // Get current language from localStorage
    const stored = localStorage.getItem('gbg-language-preference');
    const language: Language = (stored === 'en' || stored === 'pt_br') ? stored as Language : 'en';
    const { bead } = await this.beadManager.createBead(motif, center.x, center.y, 200, false, language);
    return bead;
  }

  async runFusion(): Promise<{
    inputBeadIds: string[];
    resultMotifId: string | null;
  }> {
    // Proactively sync manager to drop any orphaned beads
    try { await this.beadManager.syncWithBoard(); } catch {}

    const { inputShape, outputShape } = await this.getAreas();
    if (!inputShape || !outputShape) throw new Error('Set input and output areas.');

    const beads = await this.collectInputBeads();
    if (beads.length === 0) return { inputBeadIds: [], resultMotifId: null };

    const avg = this.computeFusionEmbedding(beads);
    if (!avg) return { inputBeadIds: beads.map((b) => b.getMotifId()), resultMotifId: null };

    const exclude = new Set<string>(beads.map((b) => b.getMotifId()));
    const motif = this.findResultMotif(avg, exclude);
    if (!motif) return { inputBeadIds: Array.from(exclude), resultMotifId: null };

    await this.spawnResult(motif);
    return { inputBeadIds: Array.from(exclude), resultMotifId: motif.id };
  }

  /**
   * Run fusion using current board selection (tracked beads only).
   * If one bead is selected, fuse it with the nearest-different motif.
   * Spawns near the selection center when possible.
   */
  async runFusionOnSelection(): Promise<{
    inputBeadIds: string[];
    resultMotifId: string | null;
  }> {
    // Selection-first discovery via text regex and name matching (works for clones)
    const selection = await window.miro.board.getSelection();
    if (!selection || selection.length === 0) return { inputBeadIds: [], resultMotifId: null };

    const center = await this.computeSelectionCenter(selection);

    // 1) Gather text items from selection and from selected groups' children
    const texts: any[] = selection.filter((i: any) => i.type === 'text');
    const groups = selection.filter((i: any) => i.type === 'group');
    for (const g of groups) {
      const itemIds: any[] = Array.isArray((g as any).items) ? (g as any).items : [];
      if (itemIds.length === 0) continue;
      try {
        const children: any[] = await window.miro.board.get({ id: itemIds });
        for (const ch of children) if (ch.type === 'text') texts.push(ch);
      } catch {}
    }

    // 2) Resolve motifs from texts
    const motifs = this.resolveMotifsFromTexts(texts);
    if (motifs.length === 0) return { inputBeadIds: [], resultMotifId: null };

    // 3) Average embeddings of unique motifs (works for 1 or many)
    const vectors = motifs.map(m => m.embedding || []).filter(arr => Array.isArray(arr) && arr.length > 0);
    if (vectors.length === 0) return { inputBeadIds: motifs.map(m => m.id), resultMotifId: null };
    const dim = vectors[0].length;
    const avg = new Array(dim).fill(0);
    for (const v of vectors) for (let i = 0; i < dim; i++) avg[i] += v[i];
    for (let i = 0; i < dim; i++) avg[i] /= vectors.length;

    // 4) Find nearest motif excluding the input set
    const exclude = new Set<string>(motifs.map(m => m.id));
    const result = this.findResultMotif(avg, exclude);
    if (!result) return { inputBeadIds: Array.from(exclude), resultMotifId: null };
    await this.spawnResult(result, center ?? undefined);
    return { inputBeadIds: Array.from(exclude), resultMotifId: result.id };
  }

  private async computeSelectionCenter(selection: any[]): Promise<{ x: number; y: number } | null> {
    let sx = 0, sy = 0, n = 0;
    for (const it of selection) {
      const x = (it as any).x, y = (it as any).y;
      if (typeof x === 'number' && typeof y === 'number') { sx += x; sy += y; n++; }
    }
    if (n > 0) return { x: sx / n, y: sy / n };
    // If only groups are selected, average their children
    try {
      const groups = selection.filter((i: any) => i.type === 'group');
      for (const g of groups) {
        const itemIds: any[] = Array.isArray((g as any).items) ? (g as any).items : [];
        if (itemIds.length === 0) continue;
        const children: any[] = await window.miro.board.get({ id: itemIds });
        for (const ch of children) {
          const x = (ch as any).x, y = (ch as any).y;
          if (typeof x === 'number' && typeof y === 'number') { sx += x; sy += y; n++; }
        }
      }
      if (n > 0) return { x: sx / n, y: sy / n };
    } catch {}
    return null;
  }

  private resolveMotifsFromTexts(texts: any[]): Motif[] {
    const normalize = (s: string) => (s || '').replace(/[\u200B-\u200D\uFEFF]/g, '').trim();
    const ID_REGEX = /\b[A-Z][A-Z0-9]*(?:\.[0-9A-Z]+)+\b/g;
    const allMotifs: Motif[] = Array.isArray(motifsData) ? (motifsData as unknown as Motif[]) : [];
    const byId = new Map<string, Motif>();
    for (const m of allMotifs) if (m.id) byId.set(m.id, m);

    // Search in both English and Portuguese names
    const resolved = new Map<string, Motif>();
    for (const t of texts) {
      const content = normalize((t as any).content || '');
      if (!content) continue;
      // ID tokens first
      const tokens = content.match(ID_REGEX) || [];
      for (const tok of tokens) {
        const m = byId.get(tok);
        if (m) resolved.set(m.id, m);
      }
      if (tokens.length > 0) continue;
      // Search in both English and Portuguese names
      let m = allMotifs.find(mm => {
        const nameEn = mm.name || '';
        const namePtBr = mm.name_pt_br || '';
        return nameEn === content || nameEn.toLowerCase() === content.toLowerCase() ||
               namePtBr === content || namePtBr.toLowerCase() === content.toLowerCase();
      });
      if (!m) {
        const lines = content.split(/\r?\n/).map(normalize).filter(Boolean);
        for (const line of lines) {
          m = byId.get(line) ||
              allMotifs.find(mm => {
                const nameEn = mm.name || '';
                const namePtBr = mm.name_pt_br || '';
                return nameEn === line || nameEn.toLowerCase() === line.toLowerCase() ||
                       namePtBr === line || namePtBr.toLowerCase() === line.toLowerCase();
              });
          if (m) break;
        }
      }
      if (m) resolved.set(m.id, m);
    }
    return Array.from(resolved.values());
  }
}


