import React, { useEffect } from 'react';
import { GBGPanel } from './components/GBGPanel';
import './App.css';

function App() {
  useEffect(() => {
    // Initialize Miro app
    if (window.miro) {
      window.miro.board.ui.on('icon:click', async () => {
        await window.miro.board.ui.openPanel({ url: '/' });
      });
    }
  }, []);

  return <GBGPanel />;
}

export default App;
