function readStringSetting(key: string, fallback: string): string {
  if (typeof window === 'undefined') return fallback;
  const stored = localStorage.getItem(key);
  return stored ?? fallback;
}

function readNumberSetting(key: string, fallback: number): number {
  if (typeof window === 'undefined') return fallback;
  const stored = localStorage.getItem(key);
  if (stored === null) return fallback;
  const parsed = parseFloat(stored);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function readBooleanSetting(key: string, fallback: boolean): boolean {
  if (typeof window === 'undefined') return fallback;
  const stored = localStorage.getItem(key);
  if (stored === null) return fallback;
  return stored === 'true';
}

function readOptionSetting<T extends readonly number[]>(
  key: string,
  options: T,
  fallback: T[number]
): T[number] {
  const stored = readNumberSetting(key, fallback);
  return options.includes(stored as T[number]) ? (stored as T[number]) : fallback;
}

function optionIndex(options: readonly number[], value: number): number {
  const idx = options.indexOf(value);
  return idx >= 0 ? idx : 0;
}

function coerceVisualFeedback(value: string): VisualFeedbackMode {
  return VISUAL_OPTIONS.includes(value as VisualFeedbackMode) ? (value as VisualFeedbackMode) : 'none';
}

