/**
 * Get I Ching hexagram information from hexagram number
 */
export function getIChingHexagram(hexagramNumber: number): IChingHexagram | null {
  if (hexagramNumber < 1 || hexagramNumber > 64) {
    return null;
  }
  
  return HEXAGRAMS[hexagramNumber - 1];
}

/**
 * Get a short representation of the I Ching hexagram for display
 */
export function getIChingDisplay(hexagramNumber: number): string {
  const hexagram = getIChingHexagram(hexagramNumber);
  if (!hexagram) {
    return '❓ Unknown';
  }
  
  return `${hexagram.symbol} ${hexagram.english}`;
}

/**
 * Get a compact representation for motif display
 */
export function getIChingCompact(hexagramNumber: number): string {
  const hexagram = getIChingHexagram(hexagramNumber);
  if (!hexagram) {
    return '❓';
  }
  
  return hexagram.symbol;
}

/**
 * Extract trigram symbols from hexagram number
 */
export function getHexagramTrigrams(hexNumber: number): { upperSymbol: string; lowerSymbol: string } | null {
  const hexagram = getIChingHexagram(hexNumber);
  if (!hexagram) return null;
  
  // Symbol is like "☳☵" - split into upper and lower
  const symbol = hexagram.symbol;
  if (symbol.length >= 2) {
    return {
      upperSymbol: symbol[0],
      lowerSymbol: symbol[1]
    };
  }
  return null;
}

/**
 * Split hexagram symbol for UI rendering (returns same as getHexagramTrigrams)
 */
export function splitHexagramSymbol(hexNumber: number): { upper: string; lower: string } | null {
  const result = getHexagramTrigrams(hexNumber);
  if (!result) return null;
  return { upper: result.upperSymbol, lower: result.lowerSymbol };
}

/**
 * Get full hexagram data from JSON file for tooltips
 */
export function getHexagramData(hexNumber: number): IChingHexagramData | null {
  if (hexNumber < 1 || hexNumber > 64) {
    return null;
  }
  const data = hexagramsData as IChingHexagramData[];
  return data[hexNumber - 1] || null;
}
