export interface FusionAreas {
  inputShapeId: string | null;
  outputShapeId: string | null;
}

export interface DistanceAreas {
  inputShapeId: string | null;
  targetShapeId: string | null;
}

interface SettingsPayload {
  fusionAreas: FusionAreas;
  version: string;
}

export class GameSettingsStorage {
  private static COLLECTION = 'gbg_settings';
  private static KEY = 'fusion_areas';
  private static VERSION = '1.0.0';

  async loadFusionAreas(): Promise<FusionAreas> {
    try {
      const data = (await window.miro.board.storage
        .collection(GameSettingsStorage.COLLECTION)
        .get(GameSettingsStorage.KEY)) as SettingsPayload | null;

      if (data && data.fusionAreas) {
        return data.fusionAreas;
      }

      return { inputShapeId: null, outputShapeId: null };
    } catch {
      return { inputShapeId: null, outputShapeId: null };
    }
  }

  async saveFusionAreas(fusionAreas: FusionAreas): Promise<void> {
    const payload: SettingsPayload = {
      fusionAreas,
      version: GameSettingsStorage.VERSION,
    };

    await window.miro.board.storage
      .collection(GameSettingsStorage.COLLECTION)
      .set(GameSettingsStorage.KEY, payload);
  }

  // Distance scoring storage helpers
  private static DISTANCE_KEY = 'distance_areas';

  async loadDistanceAreas(): Promise<DistanceAreas> {
    try {
      const data = (await window.miro.board.storage
        .collection(GameSettingsStorage.COLLECTION)
        .get(GameSettingsStorage.DISTANCE_KEY)) as { distanceAreas: DistanceAreas } | null;
      if (data && data.distanceAreas) return data.distanceAreas;
      return { inputShapeId: null, targetShapeId: null };
    } catch {
      return { inputShapeId: null, targetShapeId: null };
    }
  }

  async saveDistanceAreas(distanceAreas: DistanceAreas): Promise<void> {
    await window.miro.board.storage
      .collection(GameSettingsStorage.COLLECTION)
      .set(GameSettingsStorage.DISTANCE_KEY, { distanceAreas, version: GameSettingsStorage.VERSION });
  }
}


