import { MotifBead } from './MotifBead';
import { MotifBeadManager } from './MotifBeadManager';
import { DistanceAreas, GameSettingsStorage } from './gameSettingsStorage';
import { ScoringSystem, ScoringResult, defaultScoringSystem } from './scoringSystem';
import { getScoreColor } from './scoreColors';

type Rect = { x: number; y: number; w: number; h: number };

export class DistanceManager {
  private beadManager: MotifBeadManager;
  private storage: GameSettingsStorage;
  private scoringSystem: ScoringSystem;

  constructor() {
    this.beadManager = MotifBeadManager.getInstance();
    this.storage = new GameSettingsStorage();
    this.scoringSystem = defaultScoringSystem;
  }

  private async safeGetById(id: string): Promise<any | null> {
    try {
      const item = await window.miro.board.get({ id });
      if (!item) return null;
      return Array.isArray(item) ? item[0] || null : item;
    } catch {
      return null;
    }
  }

  private toRect(item: any): Rect {
    const w = typeof item.width === 'number' ? item.width : (item.bounds?.width ?? 0);
    const h = typeof item.height === 'number' ? item.height : (item.bounds?.height ?? 0);
    return { x: item.x, y: item.y, w, h };
  }

  private insideRect(p: { x: number; y: number }, r: Rect): boolean {
    return p.x >= r.x - r.w / 2 && p.x <= r.x + r.w / 2 && p.y >= r.y - r.h / 2 && p.y <= r.y + r.h / 2;
  }

  async getAreas(): Promise<{ distanceAreas: DistanceAreas; inputShape: any | null; targetShape: any | null }>{
    const distanceAreas = await this.storage.loadDistanceAreas();
    const inputShape = distanceAreas.inputShapeId ? await this.safeGetById(distanceAreas.inputShapeId) : null;
    const targetShape = distanceAreas.targetShapeId ? await this.safeGetById(distanceAreas.targetShapeId) : null;
    return { distanceAreas, inputShape, targetShape };
  }

  async setInputAreaFromSelection(): Promise<DistanceAreas> {
    const selection = await window.miro.board.getSelection();
    if (!selection || selection.length === 0) throw new Error('Select a shape.');
    const shape = selection.find((s: any) => s.type === 'shape') || selection[0];
    const current = await this.storage.loadDistanceAreas();
    const updated: DistanceAreas = { ...current, inputShapeId: shape.id };
    await this.storage.saveDistanceAreas(updated);
    return updated;
  }

  async setTargetAreaFromSelection(): Promise<DistanceAreas> {
    const selection = await window.miro.board.getSelection();
    if (!selection || selection.length === 0) throw new Error('Select a shape.');
    const shape = selection.find((s: any) => s.type === 'shape') || selection[0];
    const current = await this.storage.loadDistanceAreas();
    const updated: DistanceAreas = { ...current, targetShapeId: shape.id };
    await this.storage.saveDistanceAreas(updated);
    return updated;
  }

  async collectInputBeads(): Promise<MotifBead[]> {
    const { inputShape } = await this.getAreas();
    if (!inputShape) return [];
    const rect = this.toRect(inputShape);
    const beads = this.beadManager.getAllBeads();
    if (beads.length === 0) return [];

    const imageIds = beads.map(b => b.getImageId());
    let images: any[] = [];
    try { images = await window.miro.board.get({ id: imageIds, type: 'image' }); } catch { images = []; }
    const byId = new Map<string, any>();
    for (const img of images) byId.set(img.id, img);

    const result: MotifBead[] = [];
    for (const bead of beads) {
      try {
        const img = byId.get(bead.getImageId());
        const cx = img?.x, cy = img?.y;
        if (typeof cx === 'number' && typeof cy === 'number') {
          if (this.insideRect({ x: cx, y: cy }, rect)) result.push(bead);
        }
      } catch {}
    }
    return result;
  }

  async findTargetBead(): Promise<MotifBead | null> {
    const { targetShape } = await this.getAreas();
    if (!targetShape) return null;
    const rect = this.toRect(targetShape);
    const beads = this.beadManager.getAllBeads();
    if (beads.length === 0) return null;

    const imageIds = beads.map(b => b.getImageId());
    let images: any[] = [];
    try { images = await window.miro.board.get({ id: imageIds, type: 'image' }); } catch { images = []; }
    const byId = new Map<string, any>();
    for (const img of images) byId.set(img.id, img);

    let best: { bead: MotifBead; d2: number } | null = null;
    for (const bead of beads) {
      const img = byId.get(bead.getImageId());
      const cx = img?.x, cy = img?.y;
      if (typeof cx === 'number' && typeof cy === 'number') {
        if (this.insideRect({ x: cx, y: cy }, rect)) {
          const dx = cx - rect.x, dy = cy - rect.y;
          const d2 = dx * dx + dy * dy;
          if (!best || d2 < best.d2) best = { bead, d2 };
        }
      }
    }
    return best?.bead || null;
  }

  private cosine(a: number[], b: number[]): number {
    return this.beadManager.cosineSimilarity(a, b);
  }

  async scoreAndRender(scoreMode: 'similarity' | 'game' = 'similarity'): Promise<{ scored: number; skipped: number }>{
    await this.beadManager.syncWithBoard();

    const inputs = await this.collectInputBeads();
    const target = await this.findTargetBead();
    if (!target || inputs.length === 0) return { scored: 0, skipped: inputs.length };

    const targetEmb = target.getEmbedding();
    if (!targetEmb || targetEmb.length === 0) return { scored: 0, skipped: inputs.length };

    let images: any[] = [];
    try {
      images = await window.miro.board.get({ id: inputs.map(b => b.getImageId()), type: 'image' });
    } catch { images = []; }
    const byId = new Map<string, any>();
    for (const img of images) byId.set(img.id, img);

    let scored = 0, skipped = 0;
    for (const bead of inputs) {
      const emb = bead.getEmbedding();
      if (!emb || emb.length === 0) { skipped++; continue; }
      const similarity = this.cosine(emb, targetEmb);

      const img = byId.get(bead.getImageId());
      const cx = img?.x, cy = img?.y, ch = img?.height ?? 200;
      const tx = typeof cx === 'number' ? cx : 0;
      const ty = typeof cy === 'number' ? cy - (typeof ch === 'number' ? ch / 2 + 24 : 110) : 0;

      try {
        let displayText: string;
        let fontSize: number;
        let color: string;
        let metadata: any;

        if (scoreMode === 'game') {
          const scoringResult = this.scoringSystem.calculateScore(bead, target, similarity);
          displayText = scoringResult.displayText;
          fontSize = 20;
          
          // Color coding based on points
          color = getScoreColor(scoringResult.totalPoints);
          
          metadata = {
            beadId: bead.getMotifId(),
            targetId: target.getMotifId(),
            mode: 'game',
            similarity: similarity,
            gameScore: scoringResult.totalPoints,
            bonuses: scoringResult.bonuses,
            created: new Date().toISOString()
          };
        } else {
          displayText = similarity.toFixed(3);
          fontSize = 18;
          color = '#000000';
          
          metadata = {
            beadId: bead.getMotifId(),
            targetId: target.getMotifId(),
            mode: 'similarity',
            similarity: similarity,
            created: new Date().toISOString()
          };
        }

        const text = await window.miro.board.createText({
          content: displayText,
          x: tx,
          y: ty,
          style: { 
            textAlign: 'center', 
            fontSize: fontSize, 
            fontFamily: 'Arial', 
            color: color
          }
        });
        
        try {
          await text.setMetadata('distanceScore', metadata);
        } catch {}
        scored++;
      } catch { skipped++; }
    }
    return { scored, skipped };
  }

  async clearScores(): Promise<number> {
    const texts = await window.miro.board.get({ type: 'text' });
    const toRemove: string[] = [];
    for (const t of texts) {
      try {
        const meta = await t.getMetadata('distanceScore');
        if (meta) toRemove.push(t.id);
      } catch {}
    }
    if (toRemove.length > 0) {
      await window.miro.board.remove(toRemove);
    }
    return toRemove.length;
  }

  /**
   * Score only the currently selected beads against the target bead in the target area.
   */
  async scoreSelection(scoreMode: 'similarity' | 'game' = 'similarity'): Promise<{ scored: number; skipped: number }>{
    await this.beadManager.syncWithBoard();

    // Build selected beads from selection (groups and child items via groupId)
    const selection = await window.miro.board.getSelection();
    const groupIds = new Set<string>();
    for (const item of selection) {
      const type = (item as any).type;
      const id = (item as any).id;
      if (type === 'group') groupIds.add(id);
      const gid = (item as any).groupId;
      if (gid) groupIds.add(gid);
    }

    const inputs: MotifBead[] = [];
    for (const gid of Array.from(groupIds)) {
      const bead = this.beadManager.getBeadByGroupId(gid);
      if (bead) inputs.push(bead);
    }

    const target = await this.findTargetBead();
    if (!target || inputs.length === 0) return { scored: 0, skipped: inputs.length };

    const targetEmb = target.getEmbedding();
    if (!targetEmb || targetEmb.length === 0) return { scored: 0, skipped: inputs.length };

    // Fetch images for positioning text
    let images: any[] = [];
    try {
      images = await window.miro.board.get({ id: inputs.map(b => b.getImageId()), type: 'image' });
    } catch { images = []; }
    const byId = new Map<string, any>();
    for (const img of images) byId.set(img.id, img);

    let scored = 0, skipped = 0;
    for (const bead of inputs) {
      const emb = bead.getEmbedding();
      if (!emb || emb.length === 0) { skipped++; continue; }
      const similarity = this.cosine(emb, targetEmb);

      const img = byId.get(bead.getImageId());
      const cx = img?.x, cy = img?.y, ch = img?.height ?? 200;
      const tx = typeof cx === 'number' ? cx : 0;
      const ty = typeof cy === 'number' ? cy - (typeof ch === 'number' ? ch / 2 + 24 : 110) : 0;

      try {
        let displayText: string;
        let fontSize: number;
        let color: string;
        let metadata: any;

        if (scoreMode === 'game') {
          const scoringResult = this.scoringSystem.calculateScore(bead, target, similarity);
          displayText = scoringResult.displayText;
          fontSize = 22;
          if (scoringResult.totalPoints >= 1500) color = '#FF9800';
          else if (scoringResult.totalPoints >= 700) color = '#4CAF50';
          else if (scoringResult.totalPoints >= 300) color = '#2196F3';
          else color = '#666666';
          metadata = {
            beadId: bead.getMotifId(),
            targetId: target.getMotifId(),
            mode: 'game',
            similarity: similarity,
            gameScore: scoringResult.totalPoints,
            bonuses: scoringResult.bonuses,
            created: new Date().toISOString()
          };
        } else {
          displayText = similarity.toFixed(3);
          fontSize = 22;
          color = '#ff4081';
          metadata = {
            beadId: bead.getMotifId(),
            targetId: target.getMotifId(),
            mode: 'similarity',
            similarity: similarity,
            created: new Date().toISOString()
          };
        }

        const text = await window.miro.board.createText({
          content: displayText,
          x: tx,
          y: ty,
          style: {
            textAlign: 'center',
            fontSize: fontSize,
            fontFamily: 'Arial',
            color: color
          }
        });
        try { await text.setMetadata('distanceScore', metadata); } catch {}
        scored++;
      } catch { skipped++; }
    }
    return { scored, skipped };
  }
}


