/**
 * BeadStorage - Manages persistent storage of bead data using Miro's Storage Collection API
 * This ensures bead context survives page reloads and sessions
 */

export interface BeadStorageData {
  motifId: string;  // Unique bead ID (may include .1, .2 suffixes for duplicates)
  baseMotifId?: string;  // Original motif ID for reference
  groupId: string;
  imageId: string;
  textId: string;  // Main ID text
  created: string;
}

export interface BeadRegistry {
  beads: { [motifId: string]: BeadStorageData };
  version: string;
}

export class BeadStorage {
  private static STORAGE_KEY = 'gbg_bead_registry';
  private static VERSION = '1.0.0';

  /**
   * Save a bead to storage
   */
  async saveBead(motifId: string, data: BeadStorageData): Promise<void> {
    try {
      console.log(`💾 Saving bead ${motifId} to storage...`);
      
      // Load existing registry
      const registry = await this.loadBeads();
      
      // Add/update the bead
      registry.beads[motifId] = data;
      
      // Save back to storage
      await window.miro.board.storage.collection('gbg_bead_registry').set('beads', registry);
      
      console.log(`✅ Saved bead ${motifId} to storage`);
    } catch (error) {
      console.error(`❌ Error saving bead ${motifId}:`, error);
      throw error;
    }
  }

  /**
   * Load all beads from storage
   */
  async loadBeads(): Promise<BeadRegistry> {
    try {
      console.log('📂 Loading bead registry from storage...');
      
      const data = await window.miro.board.storage.collection('gbg_bead_registry').get('beads');
      
      if (data) {
        console.log(`✅ Loaded registry with ${Object.keys(data.beads || {}).length} beads`);
        return data as BeadRegistry;
      } else {
        console.log('📂 No existing registry found, creating new one');
        return {
          beads: {},
          version: BeadStorage.VERSION
        };
      }
    } catch (error) {
      console.warn('⚠️ Error loading bead registry, creating new one:', error);
      return {
        beads: {},
        version: BeadStorage.VERSION
      };
    }
  }

  /**
   * Remove a specific bead from storage
   */
  async removeBead(motifId: string): Promise<void> {
    try {
      console.log(`🗑️ Removing bead ${motifId} from storage...`);
      
      const registry = await this.loadBeads();
      delete registry.beads[motifId];
      
      await window.miro.board.storage.collection('gbg_bead_registry').set('beads', registry);
      
      console.log(`✅ Removed bead ${motifId} from storage`);
    } catch (error) {
      console.error(`❌ Error removing bead ${motifId}:`, error);
      throw error;
    }
  }

  /**
   * Clear all beads from storage
   */
  async clearAll(): Promise<void> {
    try {
      console.log('🗑️ Clearing all beads from storage...');
      
      const emptyRegistry: BeadRegistry = {
        beads: {},
        version: BeadStorage.VERSION
      };
      
      await window.miro.board.storage.collection('gbg_bead_registry').set('beads', emptyRegistry);
      
      console.log('✅ Cleared all beads from storage');
    } catch (error) {
      console.error('❌ Error clearing storage:', error);
      throw error;
    }
  }

  /**
   * Get the count of stored beads
   */
  async getBeadCount(): Promise<number> {
    try {
      const registry = await this.loadBeads();
      return Object.keys(registry.beads).length;
    } catch (error) {
      console.error('❌ Error getting bead count:', error);
      return 0;
    }
  }

  /**
   * Batch save multiple beads at once (optimized for performance)
   * Loads registry once, updates all beads, then saves once
   */
  async saveBeadsBatch(beads: Array<{ motifId: string; data: BeadStorageData }>): Promise<void> {
    if (beads.length === 0) return;
    
    try {
      console.log(`💾 Batch saving ${beads.length} beads to storage...`);
      
      // Load existing registry once
      const registry = await this.loadBeads();
      
      // Update all beads in memory
      for (const { motifId, data } of beads) {
        registry.beads[motifId] = data;
      }
      
      // Save once at the end
      await window.miro.board.storage.collection('gbg_bead_registry').set('beads', registry);
      
      console.log(`✅ Batch saved ${beads.length} beads to storage`);
    } catch (error) {
      console.error(`❌ Error batch saving beads:`, error);
      throw error;
    }
  }
}
