export interface ScaleDefinition {
  readonly tonalName: string;
  readonly degreeCount: number;
}

const SCALE_DEFINITIONS: Record<string, ScaleDefinition> = {
  ionian: { tonalName: 'major', degreeCount: 7 },
  dorian: { tonalName: 'dorian', degreeCount: 7 },
  phrygian: { tonalName: 'phrygian', degreeCount: 7 },
  lydian: { tonalName: 'lydian', degreeCount: 7 },
  mixolydian: { tonalName: 'mixolydian', degreeCount: 7 },
  aeolian: { tonalName: 'minor', degreeCount: 7 }, // natural minor
  locrian: { tonalName: 'locrian', degreeCount: 7 },
  blues: { tonalName: 'blues', degreeCount: 6 },
  major_pentatonic: { tonalName: 'major pentatonic', degreeCount: 5 },
  minor_pentatonic: { tonalName: 'minor pentatonic', degreeCount: 5 },
  harmonic_minor: { tonalName: 'harmonic minor', degreeCount: 7 },
  melodic_minor: { tonalName: 'melodic minor', degreeCount: 7 },
};

const DEFAULT_MODE_KEY = 'ionian';

function normaliseKey(input: string): string {
  return input
    .replace(/\s+/g, '_')
    .replace(/-/g, '_')
    .toLowerCase();
}

/**
 * Map various user/legacy strings to canonical scale keys defined above.
 */
export function canonicalizeModeKey(mode?: string): string {
  if (!mode) return DEFAULT_MODE_KEY;
  const key = normaliseKey(mode);
  switch (key) {
    case 'major':
    case 'ionian':
      return 'ionian';
    case 'minor':
    case 'natural_minor':
    case 'aeolian':
      return 'aeolian';
    case 'dorian':
    case 'phrygian':
    case 'lydian':
    case 'mixolydian':
    case 'locrian':
    case 'blues':
      return key;
    case 'harmonicminor':
    case 'harmonic_minor':
      return 'harmonic_minor';
    case 'melodicminor':
    case 'melodic_minor':
      return 'melodic_minor';
    case 'majorpentatonic':
    case 'pentatonicmajor':
    case 'major_pentatonic':
      return 'major_pentatonic';
    case 'minorpentatonic':
    case 'pentatonicminor':
    case 'minor_pentatonic':
      return 'minor_pentatonic';
    default:
      return DEFAULT_MODE_KEY;
  }
}

export function getScaleDefinition(modeKey?: string): ScaleDefinition {
  const key = canonicalizeModeKey(modeKey);
  return SCALE_DEFINITIONS[key] ?? SCALE_DEFINITIONS[DEFAULT_MODE_KEY];
}

export function getScaleString(tonic: string, modeKey?: string): string {
  const def = getScaleDefinition(modeKey);
  const safeTonic =
    tonic && typeof tonic === 'string'
      ? tonic.toUpperCase()
      : 'C';
  const modeParts = def.tonalName
    .split(/\s+/)
    .filter(Boolean);
  const modeSegment = modeParts.join(':');
  return modeSegment.length > 0
    ? `${safeTonic}:${modeSegment}`
    : safeTonic;
}

export function getScaleDegreeCount(modeKey?: string): number {
  const def = getScaleDefinition(modeKey);
  return def.degreeCount;
}

export const SUPPORTED_MODE_KEYS = Object.keys(SCALE_DEFINITIONS);

