/**
 * Centralized color system for scoring and highlighting
 * All score-related colors should use these constants for consistency
 */

export const SCORE_COLORS = {
  // Text highlighting (common substring matches)
  highlight: 'var(--accent-score)', // #4fc1ff - cyan for text highlights
  highlightBorder: '#4fc1ff', // Dashed border for highlighted text

  // Match types (Tarot, I Ching)
  match: {
    full: '#ffd76a', // Gold/yellow for full matches (hexagram, both rank+suit)
    fullBg: 'rgba(255,215,106,0.18)',
    partial: '#d23b3b', // Red for partial matches (trigram, rank or suit only)
    partialBg: 'rgba(210,59,59,0.15)',
  },

  // Score thresholds (for DistanceManager and similar)
  score: {
    excellent: '#FF9800', // Gold - 1500+
    good: '#4CAF50', // Green - 700-1499
    ok: '#2196F3', // Blue - 300-699
    poor: '#666666', // Gray - <300
  },

  // Bonus badge colors (using CSS variables where available)
  badge: {
    tarot: {
      full: { fg: '#ffd76a', bg: 'rgba(255,215,106,0.18)' },
      partial: { fg: '#d23b3b', bg: 'rgba(210,59,59,0.15)' },
    },
    iching: {
      hexagram: { fg: '#ffd76a', bg: 'rgba(255,215,106,0.18)' },
      trigram: { fg: '#d23b3b', bg: 'rgba(210,59,59,0.15)' },
    },
    title: { fg: 'var(--pill-title-fg)', bg: 'var(--pill-title-bg)' },
    chapter: { fg: 'var(--pill-chapter-fg)', bg: 'var(--pill-chapter-bg)' },
    code: { fg: '#b892ff', bg: 'rgba(184,146,255,0.15)' },
    substring: { fg: 'var(--accent-score)', bg: 'rgba(79,193,255,0.12)' },
    syzygy: { fg: '#00ff66', bg: '#000000' },
  },
} as const;

/**
 * Get color for a score value (for DistanceManager and similar)
 */
export function getScoreColor(score: number): string {
  if (score >= 1500) return SCORE_COLORS.score.excellent;
  if (score >= 700) return SCORE_COLORS.score.good;
  if (score >= 300) return SCORE_COLORS.score.ok;
  return SCORE_COLORS.score.poor;
}

/**
 * Get badge colors for a bonus type
 */
export function getBadgeColors(
  type: 'tarot' | 'iching' | 'title' | 'chapter' | 'code' | 'substring' | 'syzygy',
  isFullMatch?: boolean,
  isHexagram?: boolean
): { fg: string; bg: string } {
  if (type === 'tarot') {
    return isFullMatch ? SCORE_COLORS.badge.tarot.full : SCORE_COLORS.badge.tarot.partial;
  }
  if (type === 'iching') {
    return isHexagram ? SCORE_COLORS.badge.iching.hexagram : SCORE_COLORS.badge.iching.trigram;
  }
  return SCORE_COLORS.badge[type];
}

