import { useSyncExternalStore } from 'react';
import type { Language } from './languageContext';

type Listener = () => void;

const SESSION_STORAGE_KEY = 'gbg-session-v1';
const SAVE_VERSION = 1;
const XOR_KEY = 0x5a;

interface SessionSnapshot {
  seen: string[];
  version: number;
  updatedAt: number;
  language?: Language;
}

interface SessionPayload {
  v: number;
  lang?: Language;
  seen: string[];
  ts: number;
}

type LoadResult =
  | { success: true; added: number; total: number; payload: SessionPayload }
  | { success: false; error: string };

const state = {
  seen: new Set<string>(),
  version: 0,
  updatedAt: Date.now(),
  language: undefined as Language | undefined,
  restored: false,
};

const listeners = new Set<Listener>();

const isBrowser = typeof window !== 'undefined';

function notify() {
  state.version += 1;
  state.updatedAt = Date.now();
  listeners.forEach((listener) => listener());
}

function persist(language?: Language) {
  if (!isBrowser) return;
  try {
    const payload: SessionPayload = {
      v: SAVE_VERSION,
      lang: language ?? state.language,
      seen: Array.from(state.seen).sort(),
      ts: Date.now(),
    };
    const code = encodePayload(payload);
    window.localStorage.setItem(SESSION_STORAGE_KEY, code);
  } catch (error) {
    console.warn('[sessionState] Failed to persist session', error);
  }
}

function applyPayload(payload: SessionPayload, { merge }: { merge: boolean }) {
  if (!merge) {
    state.seen.clear();
  }
  let added = 0;
  for (const id of payload.seen) {
    if (!id) continue;
    if (!state.seen.has(id)) {
      state.seen.add(id);
      added += 1;
    }
  }
  if (payload.lang) {
    state.language = payload.lang;
  }
  notify();
  persist(payload.lang);
  return { added, total: state.seen.size };
}

function restoreFromStorage() {
  if (!isBrowser || state.restored) return;
  state.restored = true;
  try {
    const stored = window.localStorage.getItem(SESSION_STORAGE_KEY);
    if (!stored) return;
    const decoded = decodePayload(stored);
    if (!decoded.success) {
      console.warn('[sessionState] Failed to restore session:', decoded.error);
      return;
    }
    // Restore without notifying (silent restore on init)
    if (!decoded.payload.seen) return;
    for (const id of decoded.payload.seen) {
      if (id) state.seen.add(id);
    }
    if (decoded.payload.lang) {
      state.language = decoded.payload.lang;
    }
    // Update timestamp but don't notify listeners yet (React not ready)
    state.updatedAt = decoded.payload.ts || Date.now();
  } catch (error) {
    console.warn('[sessionState] Error restoring session', error);
  }
}

// Defer restoration to avoid triggering updates before React is ready
if (isBrowser) {
  // Restore on next tick to ensure React is initialized
  setTimeout(restoreFromStorage, 0);
}

function subscribe(listener: Listener) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

let cachedSnapshot: SessionSnapshot | null = null;
let cachedVersion = -1;

function getSnapshot(): SessionSnapshot {
  // Only create new snapshot if version changed
  if (cachedVersion !== state.version || cachedSnapshot === null) {
    cachedSnapshot = {
      seen: Array.from(state.seen).sort(),
      version: state.version,
      updatedAt: state.updatedAt,
      language: state.language,
    };
    cachedVersion = state.version;
  }
  return cachedSnapshot;
}

export function useSessionStateSnapshot(): SessionSnapshot {
  return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
}

export function markMotifSeen(id: string | undefined | null) {
  if (!id) return;
  if (!state.seen.has(id)) {
    state.seen.add(id);
    notify();
    persist();
  }
}

export function markManyMotifsSeen(ids: Iterable<string | undefined | null>) {
  let added = false;
  const idsArray = Array.from(ids);
  for (const maybeId of idsArray) {
    if (!maybeId) continue;
    if (!state.seen.has(maybeId)) {
      state.seen.add(maybeId);
      added = true;
    }
  }
  if (added) {
    notify();
    persist();
  }
}

export function clearSessionSeen() {
  if (state.seen.size === 0) return;
  state.seen.clear();
  notify();
  persist();
}

export function createSessionCode(language?: Language): { code: string; payload: SessionPayload } {
  const payload: SessionPayload = {
    v: SAVE_VERSION,
    lang: language ?? state.language,
    seen: Array.from(state.seen).sort(),
    ts: Date.now(), // Use current time for new codes
  };
  return { code: encodePayload(payload), payload };
}

export function loadSessionFromCode(code: string, options?: { merge?: boolean }): LoadResult {
  if (!code || !code.trim()) {
    return { success: false, error: 'Please paste a session code.' };
  }
  const decoded = decodePayload(code.trim());
  if (!decoded.success) {
    return decoded;
  }
  const { payload } = decoded;
  if (!Array.isArray(payload.seen)) {
    return { success: false, error: 'Malformed session payload (missing seen array).' };
  }
  const { added, total } = applyPayload(payload, { merge: options?.merge !== false });
  return { success: true, added, total, payload };
}

export function setSessionLanguage(language: Language) {
  if (state.language === language) return;
  state.language = language;
  // Only persist, don't notify (language change doesn't affect seen set)
  persist(language);
}

export function getSeenIds(): string[] {
  return Array.from(state.seen).sort();
}

export function getSeenCount(): number {
  return state.seen.size;
}

export function decodePayload(code: string): LoadResult {
  try {
    const bytes = base64UrlDecode(code);
    const decodedBytes = xorBytes(bytes);
    const json = textDecoder.decode(decodedBytes);
    const payload = JSON.parse(json) as SessionPayload;
    if (payload.v !== SAVE_VERSION) {
      return { success: false, error: `Unsupported save version: ${payload.v}` };
    }
    return { success: true, added: 0, total: 0, payload };
  } catch (error) {
    return { success: false, error: 'Invalid or corrupted session code.' };
  }
}

export function encodePayload(payload: SessionPayload): string {
  const json = JSON.stringify(payload);
  const bytes = textEncoder.encode(json);
  const obfuscated = xorBytes(bytes);
  return base64UrlEncode(obfuscated);
}

const textEncoder = new TextEncoder();
const textDecoder = new TextDecoder();

function xorBytes(bytes: Uint8Array): Uint8Array {
  const out = new Uint8Array(bytes.length);
  for (let i = 0; i < bytes.length; i += 1) {
    out[i] = bytes[i] ^ XOR_KEY;
  }
  return out;
}

function base64UrlEncode(bytes: Uint8Array): string {
  const binary = Array.from(bytes, (byte) => String.fromCharCode(byte)).join('');
  const base64 = btoaSafe(binary);
  return base64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/u, '');
}

function base64UrlDecode(value: string): Uint8Array {
  let base64 = value.replace(/-/g, '+').replace(/_/g, '/');
  while (base64.length % 4 !== 0) {
    base64 += '=';
  }
  const binary = atobSafe(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

function btoaSafe(value: string): string {
  if (typeof btoa === 'function') {
    return btoa(value);
  }
  return Buffer.from(value, 'binary').toString('base64');
}

function atobSafe(value: string): string {
  if (typeof atob === 'function') {
    return atob(value);
  }
  return Buffer.from(value, 'base64').toString('binary');
}

export type { SessionSnapshot, SessionPayload, LoadResult };
