import { Motif } from '../types/motif';
import { Language } from './languageContext';
import scaleModeMappingData from '../data/scale_mode_mapping.json';
import { canonicalizeModeKey, getScaleString } from './scales';
import { getLocalizedMotifName } from './getLocalizedMotifName';

/**
 * STRUDEL FORMAT DOCUMENTATION
 * ============================
 * 
 * Valid Scale Format:
 *   - Format: "TONIC:modeInCamelCase" (no spaces, colon separator)
 *   - Examples: "C:minor", "D#:minorPentatonic", "A:harmonicMinor"
 *   - Tonic: C, C#, D, D#, E, F, F#, G, G#, A, A#, B (uppercase, with # for sharps)
 *   - Mode: camelCase (e.g., "minorPentatonic" not "minor pentatonic")
 * 
 * Valid Note Pattern Format:
 *   - Format: "0 1 2 3" (space-separated scale degrees)
 *   - Scale degrees are 0-indexed: 0 = tonic, 1 = second degree, etc.
 *   - Plays sequentially (one note at a time) when used with n() or note()
 *   - Use "~" for rests/silence
 * 
 * Example Pattern Construction:
 *   n("[0 3 1 6 4 5 ~ 3 0 ~ 2 0 3 0 0 0]/2").scale("D:mixolydian").clip(1).piano()
 *   - n("[pattern]/N"): wraps pattern in brackets and divides by N to slow down
 *   - .scale("D:mixolydian"): applies scale (handles octaves naturally)
 *   - .clip(1): each note lasts 1 cycle (fixed)
 *   - .piano(): uses piano instrument (via REPL eval for full API access)
 * 
 * Time Control:
 *   - Division N = ceil(noteCount / 10) * speedMultiplier
 *   - 1-10 notes: base division = 1, 11-20: base = 2, 21-30: base = 3, etc.
 *   - Speed multiplier: 0.1 to 10.0 (default 1.0), lower = slower, higher = faster
 *   - Pattern duration = (1 / setcps) * finalDivision seconds
 * 
 * Letter Mapping:
 *   - Direct mapping: a=0, b=1, c=2, ..., z=25
 *   - Strudel's n().scale() handles octaves naturally (numbers outside scale range go to higher octaves)
 *   - Creates natural 3-4 octave progression
 */

interface ScaleModeMapping {
  tonic?: string;
  modeKey?: string;
  mode?: string; // legacy field
  theta?: number;
  z?: number;
}

// Load scale-mode mapping (may be empty before script generation)
const scaleModeMapping: Record<string, ScaleModeMapping> = scaleModeMappingData as Record<string, ScaleModeMapping>;

export type VisualFeedbackMode = 'none' | 'punchcard' | 'pianoroll';
export interface PlaybackSettings {
  audioEnabled: boolean;
  visualFeedback: VisualFeedbackMode;
  speed: number; // 0.1 to 10.0, default 1.0 (speed multiplier for pattern division)
  // ADSR Envelope
  attack: number; // 0.001 to 0.1, default 0.01
  sustain: number; // 0.0 to 1.0, default 0.5
  release: number; // 0.05 to 1.0, default 0.25
  // Filter
  lpf: number; // 200 to 4000, default 800
  lpenv: number; // 0 to 8, default 3
  lpdecay: number; // 0.01 to 1.0, default 0.2
  // Effects
  room: number; // 0.0 to 1.0, default 0.5
  clipLength: number; // duration multiplier passed to .clip(), default 1
}

export const DEFAULT_PLAYBACK_SETTINGS: PlaybackSettings = {
  audioEnabled: true,
  visualFeedback: 'none',
  speed: 1.0, // Default speed multiplier
  attack: 0.01,
  sustain: 0.5,
  release: 0.25,
  lpf: 800,
  lpenv: 3,
  lpdecay: 0.2,
  room: 0.5,
  clipLength: 1,
};

/**
 * Motif-to-Melody mapping system using Strudel
 * Maps motif features to musical parameters for short melody generation
 */

// Strudel API (loaded from CDN)
declare global {
  interface Window {
    initStrudel?: () => Promise<void>;
    note?: (pattern: string) => any;
    n?: (pattern: string) => any;
    sound?: (soundName: string) => any;
    s?: (pattern: string) => any;
    samples?: (arg: any, baseUrl?: string) => Promise<any>;
    soundAlias?: (existingName: string, alias: string) => void;
    scale?: (scaleName: string) => any;
    hush?: () => void;
    setcps?: (cps: number) => void;
    repl?: {
      eval?: (code: string) => any;
    };
    evalStrudel?: (code: string) => any;
  }
}

let strudelInitialized = false;
let strudelLoading = false;
let currentPattern: any = null;

/**
 * Initialize Strudel from CDN (lazy load)
 * Uses @strudel/web via CDN for minimal bundle overhead
 */
async function ensureStrudel(): Promise<boolean> {
  if (strudelInitialized) return true;
  if (strudelLoading) {
    // Wait for ongoing initialization
    return new Promise((resolve) => {
      const checkInterval = setInterval(() => {
        if (strudelInitialized) {
          clearInterval(checkInterval);
          resolve(true);
        }
      }, 100);
      setTimeout(() => {
        clearInterval(checkInterval);
        resolve(false);
      }, 5000);
    });
  }

  strudelLoading = true;
  try {
    // Load Strudel from CDN
    if (!window.initStrudel) {
      const script = document.createElement('script');
      script.src = 'https://unpkg.com/@strudel/web@latest';
      script.async = true;
      await new Promise<void>((resolve, reject) => {
        script.onload = () => {
          // Wait a bit for Strudel to be available
          setTimeout(() => resolve(), 100);
        };
        script.onerror = () => reject(new Error('Failed to load Strudel'));
        document.head.appendChild(script);
      });
    }

    // Initialize Strudel
    if (window.initStrudel) {
      await window.initStrudel();
      strudelInitialized = true;
      return true;
    }
    
    // Fallback: check if Strudel functions are already available
    if (window.note && window.sound) {
      strudelInitialized = true;
      return true;
    }
    
    return false;
  } catch (error) {
    console.warn('[motifMelody] Failed to initialize Strudel:', error);
    return false;
  } finally {
    strudelLoading = false;
  }
}

interface ScaleConfig {
  scale: string;
  modeKey: string;
  tonic: string;
}

/**
 * Resolve tonic/mode for a motif, falling back to a deterministic hash if needed.
 */
function getScaleConfig(id: string): ScaleConfig {
  const mapped = scaleModeMapping[id];
  if (mapped) {
    const tonic = (mapped.tonic || 'C').toUpperCase();
    const modeKey = canonicalizeModeKey(mapped.modeKey ?? mapped.mode ?? 'ionian');
    // Use getScaleString() helper to ensure proper camelCase format
    return {
      scale: getScaleString(tonic, modeKey),
      modeKey,
      tonic,
    };
  }

  let hash = 0;
  for (let i = 0; i < id.length; i++) {
    hash = ((hash << 5) - hash) + id.charCodeAt(i);
    hash |= 0;
  }
  const tonics = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
  const tonic = tonics[Math.abs(hash) % tonics.length];
  const modeKey = canonicalizeModeKey('ionian');
  // Use getScaleString() helper to ensure proper camelCase format
  return {
    scale: getScaleString(tonic, modeKey),
    modeKey,
    tonic,
  };
}

const DIACRITICS_REGEX = /[\u0300-\u036f]/g;
const PUNCTUATION_REGEX = /[.,;:!?'"()\\[\\]{}\\-]/;

function isWhitespace(char: string): boolean {
  return /\s/.test(char);
}

function isLetter(char: string): boolean {
  const upper = char.toUpperCase();
  return upper >= 'A' && upper <= 'Z';
}

function sanitizeChar(char: string): string {
  return char.normalize('NFD').replace(DIACRITICS_REGEX, '') || char;
}

/**
 * Build melody pattern from motif name
 * Maps letters directly: a=0, b=1, c=2, ..., z=25
 * Let Strudel's n().scale() handle octaves naturally
 */
function buildMelodyPattern(name: string): string[] {
  const melody: string[] = [];
  const A_CODE = 'A'.charCodeAt(0);

  for (const rawChar of name) {
    const baseChar = sanitizeChar(rawChar);
    if (isWhitespace(baseChar)) {
      melody.push('~');
      continue;
    }

    if (PUNCTUATION_REGEX.test(baseChar)) {
      melody.push('~');
      continue;
    }

    if (isLetter(baseChar)) {
      const upper = baseChar.toUpperCase();
      const alphaIndex = upper.charCodeAt(0) - A_CODE; // 0..25
      // Direct mapping: a=0, b=1, ..., z=25
      // Strudel's n().scale() will handle octaves naturally
      melody.push(alphaIndex.toString());
      continue;
    }

    // Any other character (digits, symbols) counts as a rest.
    melody.push('~');
  }

  // Ensure at least one note
  if (!melody.some(step => step !== '~')) {
    melody.push('0');
  }

  return melody;
}

function stepsToPattern(steps: string[]): string {
  return steps.filter(t => typeof t === 'string' && t.trim().length > 0).join(' ');
}

function prepareOverlayCanvas(): void {
  try {
    const canvas = document.getElementById('gbg-audio-canvas') as HTMLCanvasElement | null;
    if (!canvas) return;
    const dpr = (window as any).devicePixelRatio || 1;
    const rect = canvas.getBoundingClientRect();
    const width = Math.max(1, Math.floor(rect.width * dpr));
    const height = Math.max(1, Math.floor(rect.height * dpr));
    if (canvas.width !== width || canvas.height !== height) {
      canvas.width = width;
      canvas.height = height;
    }
    const ctx = canvas.getContext('2d');
    if (ctx) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
    }
    canvas.style.opacity = '1';
    canvas.style.visibility = 'visible';
  } catch {
    // ignore overlay issues
  }
}

function applyVisualFeedback(pattern: any, mode: VisualFeedbackMode) {
  if (!pattern) return pattern;
  // Use Strudel's public visualisers. We render into our own overlay canvas.
  const canvas = document.getElementById('gbg-audio-canvas') as HTMLCanvasElement | null;
  const ctx = canvas?.getContext('2d') || undefined;
  if ((mode === 'pianoroll' || mode === 'punchcard') && typeof (pattern as any).pianoroll === 'function') {
    // Do NOT pass an id: it filters to tagged events only. Our notes are untagged.
    const opts = { cycles: 2, playhead: 0.5, labels: 0, ctx };
    try {
      return (pattern as any).pianoroll(opts);
    } catch {
      // fall through
    }
  }
  return pattern;
}

// generateMelodyPattern removed - we now use name-to-notes conversion directly in playMotifMelody

/**
 * Play a short melody based on motif features
 * @param motif - The motif to generate melody from
 * @param duration - Optional duration in seconds (default: 1.5s)
 * @param language - Optional language for localized name (default: 'en')
 */
export async function playMotifMelody(
  motif: Motif,
  duration: number = 1.5,
  language: Language = 'en',
  settings?: PlaybackSettings
): Promise<void> {
  prepareOverlayCanvas();
  const storedAudioEnabled = localStorage.getItem('gbg-audio-enabled') !== 'false';
  const mergedSettings: PlaybackSettings = {
    ...DEFAULT_PLAYBACK_SETTINGS,
    audioEnabled: storedAudioEnabled,
    ...settings,
  };

  if (!mergedSettings.audioEnabled) {
    return;
  }

  const initialized = await ensureStrudel();
  if (!initialized) {
    console.warn('[motifMelody] Strudel not available');
    return;
  }

  try {
    // Use a reasonable default CPS for Strudel
    const DEFAULT_CPS = 0.5;
    if (window.setcps) {
      window.setcps(DEFAULT_CPS);
    }

    const { scale } = getScaleConfig(motif.id);
    const motifName = getLocalizedMotifName(motif, language) || motif.name || '';
    const melodySteps = buildMelodyPattern(motifName);
    const melodyPatternString = stepsToPattern(melodySteps);

    // Count non-rest notes for division calculation
    const noteCount = melodySteps.filter(step => step !== '~').length;
    if (noteCount === 0) {
      return;
    }

    // Calculate division: N = ceil(noteCount / 10) * speed
    // (Longer names get more division so longer melodies slow down; speed lets user scale the divisor.)
    const baseDivision = Math.ceil(noteCount / 10);
    const speed = Math.max(0.1, Math.min(10.0, mergedSettings.speed || 1.0));
    const finalDivision = baseDivision * speed;

    // Get synthesis parameters from settings
    const attack = mergedSettings.attack ?? DEFAULT_PLAYBACK_SETTINGS.attack;
    const sustain = mergedSettings.sustain ?? DEFAULT_PLAYBACK_SETTINGS.sustain;
    const release = mergedSettings.release ?? DEFAULT_PLAYBACK_SETTINGS.release;
    const lpf = mergedSettings.lpf ?? DEFAULT_PLAYBACK_SETTINGS.lpf;
    const lpenv = mergedSettings.lpenv ?? DEFAULT_PLAYBACK_SETTINGS.lpenv;
    const lpdecay = mergedSettings.lpdecay ?? DEFAULT_PLAYBACK_SETTINGS.lpdecay;
    const room = mergedSettings.room ?? DEFAULT_PLAYBACK_SETTINGS.room;
    const clipLength = mergedSettings.clipLength ?? DEFAULT_PLAYBACK_SETTINGS.clipLength;

    // Build pattern using REPL eval (like strudel.cc does)
    // Use sine wave with ADSR envelope, filter, and reverb effects
    const patternCode = `n("[${melodyPatternString}]/${finalDivision}").scale("${scale}").clip(${clipLength}).s('sine').attack(${attack}).sustain(${sustain}).release(${release}).lpf(${lpf}).lpenv(${lpenv}).lpdecay(${lpdecay}).room(${room})`;
    
    let melodyPattern: any = null;
    let evalMethod = 'none';
    try {
      // Use REPL eval to execute the full pattern string as code
      // This gives us access to all pattern methods
      if (window.repl?.eval) {
        try {
          melodyPattern = window.repl.eval(patternCode);
          evalMethod = 'repl.eval';
        } catch (replErr) {
          console.warn('[motifMelody] REPL eval failed:', replErr);
          console.warn('[motifMelody] Pattern code was:', patternCode);
          throw replErr;
        }
      } else if (window.evalStrudel) {
        try {
          melodyPattern = window.evalStrudel(patternCode);
          evalMethod = 'evalStrudel';
        } catch (evalErr) {
          console.warn('[motifMelody] evalStrudel failed:', evalErr);
          console.warn('[motifMelody] Pattern code was:', patternCode);
          throw evalErr;
        }
      } else {
        evalMethod = 'manual';
        const strudelN = window.n || window.note;
        if (!strudelN) {
          console.warn('[motifMelody] Strudel REPL and note helpers missing');
          return;
        }
        const patternWithBrackets = `[${melodyPatternString}]/${finalDivision}`;
        melodyPattern = strudelN(patternWithBrackets);
        if (melodyPattern && typeof melodyPattern.scale === 'function') {
          melodyPattern = melodyPattern.scale(scale);
        }
        if (melodyPattern && typeof melodyPattern.clip === 'function') {
          melodyPattern = melodyPattern.clip(clipLength);
        }
        if (melodyPattern && typeof melodyPattern.s === 'function') {
          melodyPattern = melodyPattern.s('sine');
        }
        if (melodyPattern && typeof melodyPattern.attack === 'function') {
          melodyPattern = melodyPattern.attack(attack);
        }
        if (melodyPattern && typeof melodyPattern.sustain === 'function') {
          melodyPattern = melodyPattern.sustain(sustain);
        }
        if (melodyPattern && typeof melodyPattern.release === 'function') {
          melodyPattern = melodyPattern.release(release);
        }
        if (melodyPattern && typeof melodyPattern.lpf === 'function') {
          melodyPattern = melodyPattern.lpf(lpf);
        }
        if (melodyPattern && typeof melodyPattern.lpenv === 'function') {
          melodyPattern = melodyPattern.lpenv(lpenv);
        }
        if (melodyPattern && typeof melodyPattern.lpdecay === 'function') {
          melodyPattern = melodyPattern.lpdecay(lpdecay);
        }
        if (melodyPattern && typeof melodyPattern.room === 'function') {
          melodyPattern = melodyPattern.room(room);
        }
      }
    } catch (melodyErr) {
      console.error('[motifMelody] Unable to build melody pattern', melodyErr);
      console.error('[motifMelody] Error details:', {
        message: melodyErr instanceof Error ? melodyErr.message : String(melodyErr),
        stack: melodyErr instanceof Error ? melodyErr.stack : undefined,
        patternCode,
        evalMethod,
      });
      return;
    }

    if (!melodyPattern) {
      return;
    }

    // Apply visual feedback
    const finalPattern = applyVisualFeedback(melodyPattern, mergedSettings.visualFeedback);
    currentPattern = finalPattern;

    if (typeof finalPattern.play === 'function') {
      finalPattern.play();
    }

    try {
      console.log('[motifMelody] Playing pattern:', {
        motifName,
        notePattern: melodyPatternString,
        patternCode,
        scale,
        noteCount,
        baseDivision,
        speed,
        finalDivision,
        evalMethod,
        attack,
        sustain,
        release,
        lpf,
        lpenv,
        lpdecay,
        room,
        clipLength,
        hasPlay: typeof melodyPattern?.play === 'function',
        motifId: motif.id,
      });
    } catch {
      // ignore logging errors
    }

    // Calculate pattern duration: (1 / cps) * finalDivision seconds
    const patternDurationMs = (1 / DEFAULT_CPS) * finalDivision * 1000;
    setTimeout(() => {
      stopMotifMelody();
    }, patternDurationMs);
  } catch (error) {
    console.warn('[motifMelody] Error playing melody:', error);
  }
}

/**
 * Stop any currently playing melody
 */
export function stopMotifMelody(): void {
  if (window.hush) {
    window.hush();
  }
  // Clear overlay canvas
  try {
    const canvas = document.getElementById('gbg-audio-canvas') as HTMLCanvasElement | null;
    if (canvas) {
      const ctx = canvas.getContext('2d');
      if (ctx) ctx.clearRect(0, 0, canvas.width, canvas.height);
      canvas.style.opacity = '0';
      canvas.style.visibility = 'hidden';
    }
  } catch {
    // ignore
  }
  currentPattern = null;
}

/**
 * Set audio enabled/disabled preference
 */
export function setAudioEnabled(enabled: boolean): void {
  localStorage.setItem('gbg-audio-enabled', enabled.toString());
}

/**
 * Check if audio is enabled
 */
export function isAudioEnabled(): boolean {
  return localStorage.getItem('gbg-audio-enabled') !== 'false';
}

